import pandas as pd
import numpy as np

# Load data
df = pd.read_csv("chunks_csv/moran_local_no2crime_crime_first_half_2014.csv")
adj = pd.read_csv(ADJACENCY_PATH)

# Prepare borough names and values
names = df['borough'].tolist()
values = df['value'].values
n = len(names)

# Build symmetric adjacency
neighbors = {b: set() for b in names}
for _, row in adj.iterrows():
    b, nb = row['borough'], row['neighbor']
    if b in neighbors:
        neighbors[b].add(nb)
    else:
        neighbors[b] = {nb}
    if nb in neighbors:
        neighbors[nb].add(b)
    else:
        neighbors[nb] = {b}

# Construct weight matrix W (0/1)
W = np.zeros((n, n), dtype=int)
name_to_idx = {b: i for i, b in enumerate(names)}
for i, b in enumerate(names):
    for nb in neighbors[b]:
        if nb in name_to_idx:
            j = name_to_idx[nb]
            W[i, j] = 1

# Global mean
xbar = values.mean()
print("Global mean:", xbar)

# Compute neighbor means
neighbor_means = np.array([
    (W[i] * values).sum() / W[i].sum() if W[i].sum() > 0 else np.nan
    for i in range(n)
])
print("Neighbor means for each borough:")
print(pd.DataFrame({
    'borough': names,
    'value': values,
    'neighbor_mean': neighbor_means
}))

# Compute observed local Moran's I (unnormalized)
obs_I = (values - xbar) * (W.dot(values - xbar))
print("Observed local Moran's I:")
print(pd.DataFrame({
    'borough': names,
    'local_I': obs_I
}))

# Permutation test
n_perm = 1000
perm_I = np.zeros((n_perm, n))
for k in range(n_perm):
    perm = np.random.permutation(values)
    perm_I[k] = (perm - xbar) * (W.dot(perm - xbar))

# Compute p-values (one-sided: how often permuted I >= observed I)
p_values = np.array([
    (perm_I[:, i] >= obs_I[i]).sum() / n_perm
    for i in range(n)
])
print("P-values for local Moran's I:")
print(pd.DataFrame({
    'borough': names,
    'p_value': p_values
}))

# Classify HH and LL with significance p < 0.05
labels = []
for i in range(n):
    if p_values[i] < 0.05:
        if values[i] > xbar and neighbor_means[i] > xbar:
            labels.append('HH')
        elif values[i] < xbar and neighbor_means[i] < xbar:
            labels.append('LL')
        else:
            labels.append(None)
    else:
        labels.append(None)

# Gather significant hotspots/coldspots
results = []
for i, label in enumerate(labels):
    if label in ('HH', 'LL'):
        results.append((names[i], label, obs_I[i]))

# Print results DataFrame for clarity
df_results = pd.DataFrame({
    'borough': names,
    'value': values,
    'neighbor_mean': neighbor_means,
    'local_I': obs_I,
    'p_value': p_values,
    'label': labels
})
print("Summary of boroughs with labels:")
print(df_results[df_results['label'].isin(['HH','LL'])])

# Final answer
if not results:
    print("FINAL ANSWER: none")
else:
    parts = [f"{name} ({label}, statistical method={val:.4f})" for name, label, val in results]
    print(f"FINAL ANSWER: {', '.join(parts)}")
